use rk3588_boot_support::{BootstrapEntryAction,BootstrapImageHeader,bootstrap_entry_action};
pub const BOOT_HEADER:BootstrapImageHeader=BootstrapImageHeader{vbar_el3:0x0300_B000,magic:0x4B41_5351,reserved_330:0x0003_0000,mailbox_jump:0xFF00_001C,mailbox_state:0xFF00_0004,mailbox_entry:0xFF00_0008,secondary_entry:0x26C,secondary_state:0xDEAD_BEAF,copy_src:0x800,copy_dst:0x0300_1000,copy_end:0x0300_C878,opaque_378:0x0336_BB48,marker_file_offset:0xC078};pub const POST_RELOCATION:u64=0x0300_5A44;pub const fn entry_action(marker:u32,mpidr:u64)->BootstrapEntryAction{bootstrap_entry_action(marker,mpidr,BOOT_HEADER,POST_RELOCATION)}
#[cfg(test)]mod tests{use super::*;#[test]fn header(){assert_eq!(BOOT_HEADER.marker_file_offset,0xC078);assert!(matches!(entry_action(0x4B415351,1),BootstrapEntryAction::SecondaryCpu{entry_value:0x26C,state_value:0xDEADBEAF,..}));}}
